import React, { Component} from 'react';
import {
  Box,
  Button,
  Heading,
  Grommet,
  FormField,
  Form,
  Text
} from 'grommet';
import { Home as HomeIcon, User, Lock, Add } from 'grommet-icons';

import './App.css';

const theme = {
  global: {
    colors: {
      brand: {
        dark: '#667eea',
        light: '#764ba2'
      },
      focus: '#4A90E2',
      text: {
        dark: '#2c3e50',
        light: '#7f8c8d'
      },
      background: {
        light: '#f8f9fa',
        dark: '#2c3e50'
      }
    },
    font: {
      family: '"Segoe UI", Tahoma, Geneva, Verdana, sans-serif',
      weight: 400
    }
  },
  button: {
    border: {
      radius: '8px'
    },
    primary: {
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: 'white'
    }
  },
  formField: {
    border: {
      radius: '8px'
    }
  }
};

const AppBar = (props) => (
  <Box
    className="professional-header"
    pad='medium'
    elevation='medium'
    justify='between'
    direction='row'
    align='center'
    style={{ 
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      boxShadow: '0 2px 20px rgba(102, 126, 234, 0.3)'
    }}
    {...props}
  >
    <Box direction="row" align="center" gap="medium" className="header-content">
      <HomeIcon className="home-icon" size="large" color="white" />
      <a style={{ color: 'inherit', textDecoration: 'inherit'}} href="/">
        <Heading level='2' margin='none' className="hms-title" color="white" weight="600">
          Hospital Management System
        </Heading>
      </a>
    </Box>
  </Box>
);
export class CreateAccount extends Component {
  constuctor() {
  }

  render() {

    return (
      <Grommet theme={theme} full>
        <Box fill style={{ background: 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)' }}>
          <AppBar />
          <Box
            fill
            align="center"
            justify="center"
            pad="medium">
            <Box className="modern-form" elevation="medium" round="medium" background="white">
              <Box align="center" margin={{ bottom: 'medium' }}>
                <Add size="xlarge" color="brand.dark" />
                <Heading level='2' margin={{ top: 'small', bottom: 'none' }} color="text.dark">
                  Create Account
                </Heading>
                <Text color="text.light" textAlign="center">
                  Patient Registration Form
                </Text>
              </Box>
            <Form
              onReset={event => console.log(event)}
              method="post"
              onSubmit={({ value }) => {
                console.log("Submit", value);

                fetch("http://localhost:3001/checkIfPatientExists?email=" + value.email)
                  .then(res => res.json())
                  .then(res => {
                    console.log(res.data[0]);

                    if ((res.data[0])) {
                      window.alert("An account is already associated with that email.");
                      console.log("no user found");
                    } else {
                      fetch("http://localhost:3001/makeAccount?name=" + value.firstName + "&lastname=" + value.lastName + "&email=" + value.email
                        + "&password=" + value.password + "&address=" + value.address + "&gender=" + value.gender
                        + "&conditions=" + value.conditions + "&medications=" + value.medications + "&surgeries=" + value.surgeries);
                      window.location = "/Home";
                    }
                  });
              }}>
              <FormField
                label="First Name"
                name="firstName"
                placeholder="First name"
                required
                validate={{ regexp: /^[a-z]/i }} />
              <FormField
                label="Last Name"
                name="lastName"
                required
                placeholder="Last Name"
                validate={{ regexp: /^[a-z]/i }} />
              <FormField
                label="Gender"
                name="gender"
                placeholder="Female or Male"
                required />
              <FormField
                label="Medical History - Conditions"
                name="conditions"
                placeholder="Conditions"
               />
              <FormField
                label="Medical History - Surgeries"
                name="surgeries"
                placeholder="Surgeries"
               />
              <FormField
                label="Medical History - Medications"
                name="medications"
                placeholder="Medications"
               />
              <FormField
                label="Address"
                name="address"
                placeholder="Address"
                required />
              <FormField
                label="Email"
                name="email"
                type="email"
                placeholder="Email"
                required />
              <FormField
                label="Password"
                name="password"
                placeholder="Password"
                required
                validate={{ regexp: /^(?=.{8,})(?=.*[0-9]{2})/, message: "@ least 8 characters containing 2 digits" }} />
              <Box direction="row" align="center" >
                <Button
                  style={{ textAlign: 'center' }}
                  label="Cancel"
                  fill="horizontal"
                  href="/" />
                <Button
                  label="Sign Up"
                  fill="horizontal"
                  type="submit"
                  primary />
              </Box>
              <Box
                align="center" pad="small">
                <Text>Are you a doctor?</Text>
                <Button
                  primary
                  label="I'm a doctor"
                  href="/MakeDoc" />
              </Box>
              </Form>
            </Box>
          </Box>
        </Box>
      </Grommet>
    );
  }
}

export default CreateAccount;
